const SIZE = { u8: 1, u16: 2, u32: 4, i8: 1, i16: 2, i32: 4 };

function readOne(dv, off, type) {
  switch (type) {
    case 'u8': return dv.getUint8(off);
    case 'i8': return dv.getInt8(off);
    case 'u16': return dv.getUint16(off, true);
    case 'i16': return dv.getInt16(off, true);
    case 'u32': return dv.getUint32(off, true);
    case 'i32': return dv.getInt32(off, true);
  }
  throw new Error('bad type ' + type);
}

function writeOne(dv, off, type, v) {
  switch (type) {
    case 'u8': dv.setUint8(off, v); return;
    case 'i8': dv.setInt8(off, v); return;
    case 'u16': dv.setUint16(off, v, true); return;
    case 'i16': dv.setInt16(off, v, true); return;
    case 'u32': dv.setUint32(off, v >>> 0, true); return;
    case 'i32': dv.setInt32(off, v, true); return;
  }
  throw new Error('bad type ' + type);
}

function readFields(dv, off, fields) {
  const out = {};
  for (const f of fields) {
    if (f.type === 'str') {
      let s = '';
      for (let i = 0; i < f.size; i++) {
        const c = dv.getUint8(off + i);
        if (c === 0) break;
        s += String.fromCharCode(c);
      }
      out[f.name] = s;
      off += f.size;
    } else if (f.count) {
      const a = [];
      for (let i = 0; i < f.count; i++) { a.push(readOne(dv, off, f.type)); off += SIZE[f.type]; }
      out[f.name] = a;
    } else {
      out[f.name] = readOne(dv, off, f.type);
      off += SIZE[f.type];
    }
  }
  return out;
}

/** Build a request report body (PAYLOAD bytes, without the report ID). */
export function encodeRequest(name, seq, args = {}) {
  const buf = new Uint8Array(PAYLOAD);
  const dv = new DataView(buf.buffer);
  buf[0] = CMD[name];
  buf[1] = seq & 0xFF;
  let off = 2;
  for (const f of LAYOUT[name].request) {
    const v = args[f.name];
    if (f.type === 'str') {
      const s = String(v ?? '');
      for (let i = 0; i < f.size - 1 && i < s.length; i++) buf[off + i] = s.charCodeAt(i) & 0x7F;
      off += f.size;
    } else if (f.count) {
      for (let i = 0; i < f.count; i++) { writeOne(dv, off, f.type, (v && v[i]) || 0); off += SIZE[f.type]; }
    } else {
      writeOne(dv, off, f.type, v || 0);
      off += SIZE[f.type];
    }
  }
  return buf;
}

/** Decode a response report body (DataView without the report ID). */
export function decodeResponse(dv) {
  const cmd = dv.getUint8(0);
  const name = CMD_NAME[cmd];
  const status = dv.getUint8(2);
  return {
    cmd: name ?? cmd,
    seq: dv.getUint8(1),
    status: ENUMS.status[status] ?? status,
    fields: name ? readFields(dv, 3, LAYOUT[name].response) : {},
  };
}

/** Decode a stream report body (DataView without the report ID). */
export function decodeStream(dv) {
  return readFields(dv, 0, STREAM);
}
